/* Revolution Slider Navigation Extension Stub */
(function($){
if(!window.jQuery)return;
var R=jQuery.fn.revolution;
if(!R)return;

R.createNavigation=function(container,opt){
	var nav=opt.navigation;
	if(!nav)return;

	if(nav.arrows&&nav.arrows.enable){
		var arrStyle=nav.arrows.style||"";
		var arrTmp=nav.arrows.tmp||'';
		var leftOff=parseInt(nav.arrows.left.h_offset,10)||0;
		var rightOff=parseInt(nav.arrows.right.h_offset,10)||0;
		var leftArrow=$('<div class="tp-leftarrow tparrows '+arrStyle+' noSwipe" style="position:absolute;top:50%;left:'+leftOff+'px;z-index:100;cursor:pointer;"></div>');
		if(arrTmp)leftArrow.append(arrTmp);
		leftArrow.on('click',function(){container.revprev();});
		var rightArrow=$('<div class="tp-rightarrow tparrows '+arrStyle+' noSwipe" style="position:absolute;top:50%;right:'+rightOff+'px;z-index:100;cursor:pointer;"></div>');
		if(arrTmp)rightArrow.append(arrTmp);
		rightArrow.on('click',function(){container.revnext();});
		container.append(leftArrow).append(rightArrow);
	}

	if(nav.bullets&&nav.bullets.enable){
		var bulStyle=nav.bullets.style||"";
		var bulTmp=nav.bullets.tmp||'';
		var bulSpace=parseInt(nav.bullets.space,10)||5;
		var bulVOff=parseInt(nav.bullets.v_offset,10)||0;
		var count=opt.slideamount;
		var bulSize=15;
		var totalWidth=count*bulSize+(count-1)*bulSpace;
		var bulContainer=$('<div class="tp-bullets '+bulStyle+' horizontal nav-pos-hor-center nav-pos-ver-bottom nav-dir-horizontal noSwipe" style="position:absolute;width:'+totalWidth+'px;height:'+bulSize+'px;"></div>');

		for(var i=0;i<count;i++){
			var bullet=$('<div class="tp-bullet" style="left:'+(i*(bulSize+bulSpace))+'px;top:0px;"></div>');
			if(bulTmp)bullet.append(bulTmp);
			(function(idx){
				bullet.on('click',function(){
					// Immediately update bullet state for instant feedback
					container.find('.tp-bullet').removeClass('selected');
					container.find('.tp-bullet').eq(idx).addClass('selected');
					// Then trigger the slide change
					var timer=container.parent().find('.tp-bannertimer');
					var sliderOpt=timer.data('opt');
					if(sliderOpt){
						R.callingNewSlide(sliderOpt,container,'to'+idx);
					}
				});
			})(i);
			bulContainer.append(bullet);
		}
		// First bullet matches first slide
		bulContainer.find('.tp-bullet:first').addClass('selected');
		container.append(bulContainer);
		if(typeof punchgs!=='undefined'&&punchgs.TweenLite){
			punchgs.TweenLite.set(bulContainer[0],{top:'100%',left:'50%',x:-totalWidth/2,y:-(bulSize+bulVOff)});
		}
	}
};

R.manageNavigation=function(opt){
	if(!opt||!opt.c)return;
	var bullets=opt.c.find('.tp-bullet');
	if(bullets.length>0){
		// Find the destination slide by CSS class, NOT opt.act (which is stale during transitions).
		// During swapSlideProgress the new slide has 'processing-revslide';
		// after letItFree completes it has 'active-revslide'.
		var targetSlide=opt.c.find('.processing-revslide');
		if(targetSlide.length===0){
			targetSlide=opt.c.find('.active-revslide');
		}
		if(targetSlide.length>0){
			var idx=targetSlide.index();
			bullets.removeClass('selected');
			bullets.eq(idx).addClass('selected');
		}
	}
};

R.resizeThumbsTabs=function(opt){return true;};
R.hideUnHideNav=R.showHideNavElements=R.updateNavIndexes=R.toggleState=R.unToggleState=function(){};

})(jQuery);
